query:
NODE VALUE `incoming_degree` SumAgg<INT64> = 0
TABLE `result` TYPED TABLE {`id` STRING, `total` INT64}

MATCH (:`player`)-[`edge`:`follow`]->(`dst`:`player`)
PER PATH {
  SET `dst`.@`incoming_degree` += coalesce(`edge`.`degree`, 0)
}

MATCH (`p`:`player`)
PER NODE (`p`) {
  EXPORT `p`.`id` AS `id`, `p`.@`incoming_degree` AS `total` INTO `result`
}

FOR `row` IN `result`
RETURN `row`.`id` AS `id`, `row`.`total` AS `total`
